  },
  "rotation": {
   "ranking": ">=4/5 judges correct on each of b5r1, b5r2, b5r3, b5r4 \u2014 rotation is reliably rankable at fixed scatter",
   "floor": "if b5r2 (delta=10 deg) fails but b5r3 (delta=20 deg) passes, perceptual floor is between 10 and 20 deg"
  },
  "cross_factor": {
   "scatter_question": ">=4/5 judges pick left (high-scatter side) on b5x1 \u2014 scatter does not read as rotation",
   "rotation_question": ">=4/5 judges pick right (high-rotation side) on b5x2 \u2014 rotation does not read as scatter",
   "verdict_rule": "both pass -> scatter and rotation are separable, independently judgeable; either fails -> cross-factor confusion above threshold, factors not separable at these deltas"
  },
  "opacity_falloff": {
   "extreme": ">=4/5 correct on b5o1 (p1) and b5o3 (p2) \u2014 fading is detectable at both stroke counts",
   "jnd": "b5o2 (delta=0.5 at p1) and b5o4 (delta=0.5 at p2) agreement gives the JND; if both fail, JND is above 0.5",
   "independence": "agreement on b5o1 vs b5o3 and b5o2 vs b5o4 within each other's bootstrap CIs -> opacity_falloff reads independently of stroke count; if p1 pairs pass but p2 pairs fail (or vice versa), opacity_falloff interacts with overlap density"
  },
  "general": "any scored pair with a 50/50 judge split is a stimulus failure, not human noise: regenerate at higher parameter delta in the next batch"
 },
 "adaptive_rules": {
  "catch_fail": "a judge answering >1 catch pair with a side choice instead of 'no difference' is excluded from aggregates; recruit a replacement to hold n=5",
  "scatter_fail": "if 0v2 fails but 2v5 passes, floor is between 2 and 5: next batch probes 2v4 and 3v5",
  "rotation_fail": "if 0v10 fails but 10v30 passes, floor is between 10 and 30 deg: next batch probes 10v20 and 15v25",
  "cross_factor_fail": "if b5x1 fails (judges pick high-rotation side for scatter question), scatter and rotation are confounded at these deltas: next batch increases scatter delta to 12 and retests; if still fails, factors collapse to composite",
  "opacity_fail": "if 0v0.5 fails but 0v1.0 passes, JND is between 0.5 and 1.0: next batch probes 0.5v0.75 and 0.6v0.8",
  "opacity_independence_fail": "if p1 pairs pass but p2 pairs fail, opacity_falloff interacts with stroke count: next batch tests at passes=3 and with explicit overlap density control",
  "stimulus_fail": "50/50 splits get regenerated at higher contrast next batch and logged as stimulus-quality data",
  "convergence": "two consecutive batches with agreement values inside each other's bootstrap CIs at target n ends the loop for that dimension; the plateau is the metric's honest ceiling"
 },
 "registry_consequences": {
  "scatter_pass": "scatter -> validated as independent mark-making axis (mark_scatter)",
  "rotation_pass": "rotation -> validated as independent mark-making axis (mark_rotation)",
  "cross_factor_pass": "scatter and rotation -> validated as separable, independently judgeable; both promoted to own axes",
  "cross_factor_fail": "scatter and rotation -> collapsed into composite mark_making factor with evidence",
  "opacity_pass": "opacity_falloff -> validated as fading axis, independent of stroke count (opacity_fade)",
  "opacity_independence_fail": "opacity_falloff -> validated as fading but interacts with stroke count; flagged with interaction term",
  "opacity_fail": "opacity_falloff -> stays measurable, JND work queued"
 }
